import {bindAmountInput,parseAmount} from './amount-input.js';import {makeChoice} from './simple-choice.js';
export function initResearchInputs({market,node,notify}){let entries=[];const panel=node('details','manual-market-source');panel.innerHTML='<summary>Comparar un anuncio que revisaste en Marketplace o una autoventa</summary><p>Algunos portales piden iniciar sesión. Si ya revisaste el anuncio, puedes incorporarlo sin compartir tu cuenta. Se identifica como referencia aportada por ti.</p><div class="fields"><label>Enlace público del anuncio<input id="market-ad-url" type="url" placeholder="https://…"></label><label>Título del anuncio<input id="market-ad-title" placeholder="Marca, modelo, versión y año reales del anuncio"></label><label>Precio anunciado<input id="market-ad-price" inputmode="decimal"></label><label>Moneda del anuncio<select id="market-ad-currency"><option value="USD">US$ · Dólares</option><option value="BOB">Bs · Bolivianos</option></select></label><label class="source-details">Texto del anuncio / características<textarea id="market-ad-details" rows="3" placeholder="Copia condición, motor, transmisión, tracción, ciudad y demás datos visibles del anuncio."></textarea></label></div><label class="verified-source"><input type="checkbox" id="market-ad-confirm">Revisé el precio total, moneda, año, versión, características y ubicación del anuncio.</label><button type="button" id="market-ad-add">Añadir referencia revisada</button><div id="market-ad-list"></div>';market.append(panel);const amount=bindAmountInput(panel.querySelector('#market-ad-price'));makeChoice(panel.querySelector('#market-ad-currency'),null,{node,label:'Moneda del anuncio'});const list=panel.querySelector('#market-ad-list');function render(){list.replaceChildren();for(const [i,entry]of entries.entries()){const row=node('div','manual-source-row'),text=node('span','',`${entry.title} · ${entry.currency} ${Number(entry.price).toLocaleString('en-US')}`),remove=node('button','','Quitar');remove.type='button';remove.onclick=()=>{entries.splice(i,1);render();};row.append(text,remove);list.append(row);}}
 panel.querySelector('#market-ad-add').onclick=()=>{const url=panel.querySelector('#market-ad-url').value.trim(),title=panel.querySelector('#market-ad-title').value.trim(),details=panel.querySelector('#market-ad-details').value.trim(),price=parseAmount(panel.querySelector('#market-ad-price').value),currency=panel.querySelector('#market-ad-currency').value;try{if(new URL(url).protocol!=='https:')throw Error();}catch{notify('Introduce un enlace HTTPS válido al anuncio.',{type:'error',id:'manual-source'});return;}if(!title||!details||!(price>0)||!panel.querySelector('#market-ad-confirm').checked){notify('Completa el precio, el texto del anuncio y confirma que revisaste sus datos.',{type:'warning',id:'manual-source'});return;}if(entries.some(e=>e.url===url)){notify('Ese anuncio ya está añadido.',{type:'warning',id:'manual-source'});return;}entries.push({url,title,details,price,currency,confirmed:true});panel.querySelector('#market-ad-confirm').checked=false;render();notify('Referencia añadida. Vuelve a calcular para comprobar si corresponde a este vehículo.',{type:'success',id:'manual-source'});};
 const info=node('div','market-source-coverage');market.querySelector('#research-status').after(info);return{capture:()=>structuredClone(entries),open(vehicle){entries=(vehicle?.comparables||[]).filter(r=>r.providedByAdmin).map(r=>({...r,confirmed:true,details:r.details||''}));render();info.replaceChildren();},summary(result){info.replaceChildren(...(result.searchedSources||[]).map(s=>{const item=node('div');item.append(node('strong','',s.name),node('span','',s.verified?`${s.verified} precios compatibles`:s.found?'Fuentes revisadas, sin precio compatible':'Sin anuncios públicos verificables en esta consulta'));return item;}));}};
}
